    void AddToggle(FlowLayoutPanel panel,string title,string detail,bool value,Action<Settings,bool> update){SettingsToggle toggle=new SettingsToggle(title,detail,value);if(String.IsNullOrEmpty(detail)){toggle.Height=52;toggle.Margin=new Padding(0,0,0,7);}toggle.CheckedChanged+=(s,e)=>{Settings next=Clone(latest());update(next,toggle.Checked);Commit(next);};panel.Controls.Add(toggle);}
    public static string NormalizeApp(string text){text=(text??"").Trim();return text.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)?text.Substring(0,text.Length-4).ToLowerInvariant():text.ToLowerInvariant();}
    static ComboBox Combo(string[] items,string selected){ComboBox box=new ComboBox {Width=540,DropDownStyle=ComboBoxStyle.DropDownList,FlatStyle=FlatStyle.Flat,Margin=new Padding(0,0,0,12)};box.Items.AddRange(items);box.SelectedItem=selected;if(box.SelectedIndex<0)box.SelectedIndex=0;return box;}
